## Code Example
```javascript
// Architecture wiring sketch
function routeUtterance(utterance) {
  // On-device processing pipeline
  const sentiment = detectSentimentOnDevice(utterance);
  const language = detectLanguage(utterance);

  // Cloud fallback escalation logic
  if (requiresEmotionAnalysis(sentiment)) {
    const emotions = analyzeEmotionsCloud(utterance, language);
    return determineRouting(sentiment, emotions);
  }
  return determineRouting(sentiment, null);
}
```

